'use strict';
const ispmanView={q:'',service:'',page:1,request:0,previewRequest:0};
async function renderIspmanOverview(){
 ispmanView.previewRequest++;

 if(state.session?.user.role!=='admin'){$('#main').innerHTML=notice('Owner access required','ISPman imports include private customer and financial information.',true);return;}
 $('#main').innerHTML=heading('ISPman overview','Customer records from your latest manual import.')+`<div class="ispman-page"><div class="notice"><div><strong>ISPman remains in charge</strong><p>Imports update this overview only. Customer logins, packages, wallets, payments and router settings in netops stay unchanged.</p><p>Manual snapshots · no automatic sync · payment history is not included.</p></div></div><section class="card ispman-import"><h2>Import customers</h2><p>In ISPman, export customers to Excel, then save that sheet as <strong>CSV UTF-8</strong>. Remove any password or credential columns. Choose the service that matches the export.</p><form id="ispman-import-form"><div class="ispman-inputs"><label>Service<select id="ispman-import-service"><option value="pppoe">PPPoE</option><option value="hotspot">Hotspot</option></select></label><label>Customer CSV<input id="ispman-file" type="file" accept=".csv,text/csv"></label><button class="button secondary" type="submit">Preview import</button></div><label>Or paste CSV UTF-8<textarea id="ispman-paste" rows="5" maxlength="4194304" placeholder="Paste the header row and customer rows here"></textarea></label><p class="field-note">PPPoE requires Username and Package. Hotspot requires Payment Wallet and a Package column (blank packages are kept). Optional: Name, Phone Number, Email, Balance, Available Balance, Current Balance, Currency, Expires At, Status, Last Device, Last Seen, Active Connects. Maximum 5,000 rows / 4 MiB. Missing customers are retained.</p><p id="ispman-error" class="form-error" role="alert"></p></form><div id="ispman-preview" aria-live="polite"></div></section><section class="card ispman-records"><div id="ispman-summary" aria-live="polite"></div><div class="ispman-inputs"><label>Search customers<input id="ispman-query" type="search" value="${h(ispmanView.q)}" placeholder="Name, username, wallet, phone or package"></label><label>Show service<select id="ispman-filter"><option value="">All services</option><option value="pppoe" ${ispmanView.service==='pppoe'?'selected':''}>PPPoE</option><option value="hotspot" ${ispmanView.service==='hotspot'?'selected':''}>Hotspot</option></select></label></div><div id="ispman-results" aria-live="polite">Loading imported records…</div></section></div>`;
 let timer;$('#ispman-query').oninput=e=>{ispmanView.q=e.target.value;ispmanView.page=1;clearTimeout(timer);timer=setTimeout(loadIspmanOverview,200);};
 $('#ispman-filter').onchange=e=>{ispmanView.service=e.target.value;ispmanView.page=1;loadIspmanOverview();};
 const form=$('#ispman-import-form'),file=$('#ispman-file'),service=$('#ispman-import-service'),pasted=$('#ispman-paste');
 const clear=()=>{ispmanView.previewRequest++;$('#ispman-preview').replaceChildren();$('#ispman-error').textContent='';};file.onchange=clear;service.onchange=clear;pasted.oninput=clear;
 form.onsubmit=async event=>{
  event.preventDefault();clear();const request=ispmanView.previewRequest,selected=file.files[0],svc=service.value,button=form.querySelector('[type=submit]');button.disabled=true;
  try{if(selected&&!/\.csv$/i.test(selected.name))throw new Error('Save the Excel export as CSV UTF-8 first');if(selected&&pasted.value.trim())throw new Error('Choose a file or paste CSV, not both');if(selected?.size>4194304)throw new Error('Choose a file smaller than 4 MiB');
   const csv=selected?await selected.text():pasted.value;if(!csv.trim())throw new Error('Choose a CSV file or paste the converted CSV');if(new TextEncoder().encode(csv).length>4194304)throw new Error('Use CSV smaller than 4 MiB');if(state.page!=='ispman-overview'||request!==ispmanView.previewRequest)return;
   // Reject credential headings locally as well, before sending the file to netops.
   if(/password|secret|token|api.?key|auth.?key/i.test(csv.split(/\r?\n/,1)[0]))throw new Error('Remove password, secret and credential columns before uploading');
   const result=await api('ispman/preview','POST',{service:svc,csv});if(state.page!=='ispman-overview'||request!==ispmanView.previewRequest)return;
   const issues=[...result.errors.map(x=>({...x,type:'Error'})),...result.warnings.map(x=>({...x,type:'Note'}))];
   $('#ispman-preview').innerHTML=`<h3>Review before importing</h3><p>${result.total} rows · ${result.creates} new · ${result.updates} updated · ${result.unchanged} unchanged</p><p>Only the separate ISPman overview will be saved. A netops account match below is a suggestion; accounts will not be merged or changed.</p>${issues.length?`<ul class="ispman-issues">${issues.slice(0,30).map(x=>`<li>${h(x.type)} · row ${x.line}: ${h(x.message)}</li>`).join('')}</ul>${issues.length>30?'<p>Only the first 30 issues are shown.</p>':''}`:''}<div class="ispman-preview-list">${result.rows.slice(0,20).map(x=>`<article><strong>${h(x.username||x.externalId)}</strong><span>${h(x.package||'No package supplied')}</span><small>${h(x.action)} · ${x.match?'Netops match: '+h(x.match.name):x.ambiguousMatch?'Multiple netops matches':'No netops match'}</small></article>`).join('')}</div>${result.rows.length>20?'<p>Showing the first 20 customer previews.</p>':''}${!result.errors.length?'<label class="check-label"><input id="ispman-confirm" type="checkbox"> I reviewed the service, customer changes and any notes above.</label><button id="ispman-commit" class="button primary" disabled>Import into overview</button>':'<p class="form-error">Fix the errors and preview the file again.</p>'}`;
   const confirm=$('#ispman-confirm'),commit=$('#ispman-commit');if(confirm)confirm.onchange=()=>{commit.disabled=!confirm.checked;};
   if(commit)commit.onclick=async()=>{commit.disabled=true;confirm.disabled=true;try{
    await api('ispman/import','POST',{service:svc,csv,digest:result.digest,revision:result.revision});if(state.page!=='ispman-overview'||request!==ispmanView.previewRequest)return;
    $('#ispman-preview').innerHTML='<p role="status">Import saved to the ISPman overview.</p>';file.value='';pasted.value='';await loadIspmanOverview();toast('ISPman overview updated');
   }catch(error){if(state.page==='ispman-overview'){clear();$('#ispman-error').textContent=error.message+' Preview again before retrying.';}}};
  }catch(error){if(state.page==='ispman-overview'&&request===ispmanView.previewRequest)$('#ispman-error').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}
 };
 await loadIspmanOverview();
}
async function loadIspmanOverview(){
 const request=++ispmanView.request;try{const result=await api('ispman?'+new URLSearchParams({q:ispmanView.q,service:ispmanView.service,page:ispmanView.page}));if(state.page!=='ispman-overview'||request!==ispmanView.request)return;
  $('#ispman-summary').innerHTML=`<h2>Imported customers</h2><p><strong>${result.counts.pppoe} PPPoE · ${result.counts.hotspot} Hotspot</strong></p><p>${result.lastImport?'Last imported '+h(stamp(result.lastImport.at))+' · '+h(result.lastImport.service.toUpperCase())+' · '+result.lastImport.total+' rows':'No customer export imported yet.'}</p><p class="field-note">Dates below show when netops received each record. They do not prove it is current in ISPman.</p>`;
  $('#ispman-results').innerHTML=`<div class="ispman-customer-list">${result.items.map(x=>`<article><div><strong>${h(x.name||x.username||x.externalId)}</strong><p>${h(x.username||'No username supplied')} · ${h(x.service.toUpperCase())}</p><small>${h(x.externalId||'No payment wallet supplied')}</small></div><dl><div><dt>Package in ISPman</dt><dd>${h(x.package||'Not supplied')}</dd></div><div><dt>Available balance in export</dt><dd>${h(x.availableBalanceText?((x.currency||'')+' '+x.availableBalanceText).trim():'Not supplied')}</dd></div><div><dt>Current balance in export</dt><dd>${h(x.currentBalanceText?((x.currency||'')+' '+x.currentBalanceText).trim():'Not supplied')}</dd></div>${x.balanceText?`<div><dt>Other balance text in export</dt><dd>${h(x.balanceText)}</dd></div>`:''}<div><dt>Expiry in export</dt><dd>${h(x.expiryText||'Not supplied')}</dd></div><div><dt>Contact</dt><dd>${h([x.phone,x.email].filter(Boolean).join(' · ')||'Not supplied')}</dd></div><div><dt>Netops account match</dt><dd>${x.match?h(x.match.name)+' (reference only)':x.ambiguousMatch?'Multiple matches — review needed':'No matching account'}</dd></div><div><dt>Last imported</dt><dd>${h(stamp(x.lastImportedAt))}</dd></div>${x.lastDevice?`<div><dt>Last device in export</dt><dd>${h(x.lastDevice)}</dd></div>`:''}${x.lastSeenText?`<div><dt>Last seen in export</dt><dd>${h(x.lastSeenText)}</dd></div>`:''}${x.activeConnectsText?`<div><dt>Active connects in export</dt><dd>${h(x.activeConnectsText)}</dd></div>`:''}${x.status?`<div><dt>Source status</dt><dd>${h(x.status)}</dd></div>`:''}</dl></article>`).join('')||'<p class="list-empty">No imported customers match this view.</p>'}</div><div class="ispman-paging"><span>${result.total} records · page ${result.page} of ${result.pages}</span><button class="button secondary" id="ispman-prev" ${result.page<=1?'disabled':''}>Previous</button><button class="button secondary" id="ispman-next" ${result.page>=result.pages?'disabled':''}>Next</button></div>`;
  $('#ispman-prev').onclick=()=>{ispmanView.page=result.page-1;loadIspmanOverview();};$('#ispman-next').onclick=()=>{ispmanView.page=result.page+1;loadIspmanOverview();};
 }catch(error){if(state.page==='ispman-overview'&&request===ispmanView.request)$('#ispman-results').textContent=error.message;}
}
